 const makeDetails=(node,type)=>{const details=document.createElement('details');details.className=`${node.className} ${type}`;details.open=false;const summary=document.createElement('summary');if(type==='lesson-details'){const mark=node.querySelector('.callout-mark'),label=node.querySelector('p'),title=node.querySelector('h3');summary.className='lesson-summary';summary.append(mark.cloneNode(true));const copy=document.createElement('div');copy.append(label.cloneNode(true));summary.append(copy);const body=document.createElement('div');body.className='lesson-expanded';if(title.textContent.trim())body.append(title);const list=node.querySelector('ul');if(list){const panel=node.closest('.objective-panel'),baseIds=[...panel.querySelectorAll('[data-chord-card]')].map(card=>card.dataset.chordCard),noteIds=[...new Set(baseIds.flatMap(id=>[id,...(byId[id]?.variants||[])]))],hasOptions=noteIds.length>baseIds.length;if(hasOptions){const optionNote=document.createElement('li');optionNote.innerHTML='Harder shapes may include alternate playing options. Use the arrows in the chord header to compare them. Some substitutes, such as Fmaj7 or B♭maj7, are slightly different chords that can stand in while the main shape is still developing.';list.append(optionNote);}noteIds.forEach(id=>{const chord=byId[id];if(!chord?.tip)return;const note=document.createElement('li');note.innerHTML=`<strong>${chord.name}:</strong> ${chord.tip}`;list.append(note);});body.append(list);}details.append(summary,body);}else if(type==='exercise-details'){const grid=node.querySelector('.exercise-grid'),panel=node.closest('[data-objective]'),objective=panel?.dataset.objective||'one',heading=node.querySelector('.section-heading p')?.textContent||'EXERCISES',rhythm=objective==='one'?'Objective 1 uses four steady down-strums.':objective==='two'?'Objective 2 adds the first up-strums: D D D D-up and D D D-up D-up.':'Objective 3 mixes the strumming patterns learned so far and introduces skipped strokes.';const shell=document.createElement('section');shell.className=`practice-drawers practice-count-${grid?.children.length||0}`;const intro=document.createElement('div');intro.className='practice-transition';intro.innerHTML=`<div><p>${heading}</p><h2>Common Chord Pairs</h2></div><span>Common transitions heard together in songs.</span>`;const instructions=document.createElement('details');instructions.className='practice-instructions';instructions.innerHTML=`<summary><span class="drawer-toggle" aria-hidden="true"></span><span><small>EXPAND FOR MORE INFO</small><strong>How to practice</strong></span></summary><div class="practice-instructions-body"><p><strong>Why these exercises:</strong> chord pairs are transitions heard together constantly in songs. Exercise 4 joins them into a repeating four-measure pattern—the basic frame behind much of modern Western music.</p><p><strong>Strumming:</strong> ${rhythm} If that pattern does not make sense yet, substitute four down-strums—<strong>D D D D</strong>—and keep the beat moving.</p><p>Practice moving from chord to chord using the indicated pattern. Count <strong>“One, Two, Three, Four”</strong> with each downbeat, and sync your foot tap with the beat.</p><p>There are no pauses between chords. If the shape is not perfect, keep strumming and adjust your fingers throughout the measure.</p><p>Repeat each exercise daily until the transition feels smooth. Work on about two groups a day for several weeks—roughly 15–30 minutes of practice.</p></div>`;shell.append(intro,instructions);[...(grid?.children||[])].forEach((card,index)=>{const names=[...card.querySelectorAll('.preview-chord')].map(button=>button.textContent.trim()),tab=document.createElement('button'),body=document.createElement('div');tab.type='button';tab.className=`practice-exercise-tab${index===3?' progression-exercise-tab':''}`;tab.setAttribute('aria-pressed','false');tab.innerHTML=`<span class="exercise-tab-number">${index+1}</span><span class="drawer-copy"><small>EXERCISE ${index+1}${index===3?' · FIRST PROGRESSION':''}</small><strong>${names.join(' → ')}</strong></span>`;body.className=`practice-exercise-panel${index===3?' progression-exercise-panel':''}`;body.hidden=true;body.append(card);tab.addEventListener('click',()=>{const wasOpen=tab.getAttribute('aria-pressed')==='true';shell.querySelectorAll('.practice-exercise-tab').forEach(button=>button.setAttribute('aria-pressed','false'));shell.querySelectorAll('.practice-exercise-panel').forEach(panel=>panel.hidden=true);if(!wasOpen){tab.setAttribute('aria-pressed','true');body.hidden=false;}syncPageLock();});shell.append(tab,body);});node.replaceWith(shell);return;}else{const eyebrow=node.querySelector(':scope > p'),title=node.querySelector(':scope > h3'),card=node.querySelector(':scope > .change-card');summary.className='progression-summary';summary.append(eyebrow.cloneNode(true),title.cloneNode(true));const body=document.createElement('div');body.className='progression-body';if(card){if(card.querySelectorAll('.music-measure').length===4){const cue=document.createElement('p');cue.className='progression-reading-cue';cue.innerHTML='<span class="desktop-reading-cue">Read left to right through all four measures.</span><span class="mobile-reading-cue">Read across, then continue on row 2.</span>';body.append(cue);}body.append(card);}details.append(summary,body);}node.replaceWith(details);};
