 const show=(id,lock=false)=>{const c=byId[id];if(!c)return;clearTimeout(timer);locked=lock;const kind=c.variantOf?'CHORD OPTION':'CHORD PREVIEW';content.innerHTML=`<div class="preview-heading"><div><p>${kind}</p><h2>${c.name}</h2></div><button type="button" class="play-chord" data-play-chord="${c.id}" aria-label="Play ${c.name} chord">${playIcon()}</button></div>${diagram(c)}<span>${c.tip}</span>${variationLinks(c)}`;preview.hidden=false;backdrop.hidden=!lock;preview.classList.toggle('locked',lock);preview.setAttribute('aria-modal',String(lock));};
