 const showCourse=course=>{currentCourse=course;const family=course.startsWith('bar-')?'bar':course.startsWith('uke-')?'uke':'guitar';section.querySelector('.objective-tabs .nav-tier-label').textContent=family==='guitar'?'2 · Choose an objective':'3 · Choose an objective';section.querySelectorAll('[data-course-tab]').forEach(button=>{const target=button.dataset.courseTab,selected=target==='guitar'?family==='guitar':target.startsWith('bar-')?family==='bar':family==='uke';button.setAttribute('aria-pressed',String(selected));});pathTabs.hidden=family==='guitar';section.querySelectorAll('[data-path-kind]').forEach(button=>button.setAttribute('aria-pressed',String(course.endsWith(button.dataset.pathKind))));showObjective('one');};
